-- Grade da semana da Antena Rock (versão 2): blocos por estilo de dia, Elvis de segunda a sexta às 11h
-- e especiais de 30 minutos de uma banda só entre 23h e 7h, intercalados com a Madrugada.
-- ATENÇÃO: apaga todos os programas e a grade atual e cria de novo. O histórico do que tocou é mantido.
-- Uso no servidor: cd /opt/radio-online && sudo docker compose -f docker-compose.prod.yml exec -T postgres sh -c 'psql -v ON_ERROR_STOP=1 -U "$POSTGRES_USER" -d "$POSTGRES_DB"' < infra/server/grade-semana.sql
BEGIN;
DELETE FROM "ProgramSlot";
DELETE FROM "Program";
CREATE TEMP TABLE ids (k text PRIMARY KEY, id int) ON COMMIT DROP;
WITH p AS (INSERT INTO "Program" (title, host, category, description, color, "mediaFolder") VALUES ('Madrugada Antena Rock', 'Auto-DJ', 'Rock', 'Rotação geral com o acervo inteiro durante a madrugada.', '#6d28d9', NULL) RETURNING id) INSERT INTO ids SELECT 'madrugada', id FROM p;
WITH p AS (INSERT INTO "Program" (title, host, category, description, color, "mediaFolder") VALUES ('Antena Rock Mix', 'Auto-DJ', 'Rock', 'Rotação geral com o acervo inteiro.', '#dc2626', NULL) RETURNING id) INSERT INTO ids SELECT 'mix', id FROM p;
WITH p AS (INSERT INTO "Program" (title, host, category, description, color, "mediaFolder") VALUES ('Clássicos Internacionais', 'Auto-DJ', 'Classic Rock', 'Clássicos do rock internacional.', '#ea580c', 'Clássicos Internacionais') RETURNING id) INSERT INTO ids SELECT 'ci', id FROM p;
WITH p AS (INSERT INTO "Program" (title, host, category, description, color, "mediaFolder") VALUES ('Rock Anos 70', 'Auto-DJ', 'Rock / Anos 70', 'Rock, punk e glam dos anos 70, com David Bowie.', '#ca8a04', 'Rock Anos 70|David Bowie') RETURNING id) INSERT INTO ids SELECT 'r70', id FROM p;
WITH p AS (INSERT INTO "Program" (title, host, category, description, color, "mediaFolder") VALUES ('Rock Nacional', 'Auto-DJ', 'Rock Brasileiro', 'Clássicos do rock brasileiro.', '#16a34a', 'Clássicos Nacionais') RETURNING id) INSERT INTO ids SELECT 'nac', id FROM p;
WITH p AS (INSERT INTO "Program" (title, host, category, description, color, "mediaFolder") VALUES ('Pesado', 'Auto-DJ', 'Heavy Metal', 'Iron Maiden, Megadeth e Black Sabbath.', '#475569', 'Iron Maiden|Megadeth|Black Sabbath') RETURNING id) INSERT INTO ids SELECT 'pesado', id FROM p;
WITH p AS (INSERT INTO "Program" (title, host, category, description, color, "mediaFolder") VALUES ('Alternativo', 'Auto-DJ', 'Rock Alternativo', 'Grunge, indie e rock alternativo.', '#0891b2', 'Alice In Chains|The Smashing Pumpkins|Red Hot Chili Peppers|The Smiths|Coldplay') RETURNING id) INSERT INTO ids SELECT 'alt', id FROM p;
WITH p AS (INSERT INTO "Program" (title, host, category, description, color, "mediaFolder") VALUES ('Arena Rock', 'Auto-DJ', 'Hard Rock', 'Kiss, Def Leppard e Queen.', '#db2777', 'Kiss|Def Leppard|Queen') RETURNING id) INSERT INTO ids SELECT 'arena', id FROM p;
WITH p AS (INSERT INTO "Program" (title, host, category, description, color, "mediaFolder") VALUES ('Especial Elvis Presley', 'Auto-DJ', 'Rock and Roll', 'Uma hora só de Elvis Presley, de segunda a sexta.', '#be123c', 'Elvis Presley') RETURNING id) INSERT INTO ids SELECT 'elvis', id FROM p;
WITH p AS (INSERT INTO "Program" (title, host, category, description, color, "mediaFolder") VALUES ('Especial Iron Maiden', 'Auto-DJ', 'Especial', 'Meia hora só de Iron Maiden, na madrugada.', '#1e293b', 'Iron Maiden') RETURNING id) INSERT INTO ids SELECT 'esp:Iron Maiden', id FROM p;
WITH p AS (INSERT INTO "Program" (title, host, category, description, color, "mediaFolder") VALUES ('Especial The Smashing Pumpkins', 'Auto-DJ', 'Especial', 'Meia hora só de The Smashing Pumpkins, na madrugada.', '#0e7490', 'The Smashing Pumpkins') RETURNING id) INSERT INTO ids SELECT 'esp:The Smashing Pumpkins', id FROM p;
WITH p AS (INSERT INTO "Program" (title, host, category, description, color, "mediaFolder") VALUES ('Especial Kiss', 'Auto-DJ', 'Especial', 'Meia hora só de Kiss, na madrugada.', '#9f1239', 'Kiss') RETURNING id) INSERT INTO ids SELECT 'esp:Kiss', id FROM p;
WITH p AS (INSERT INTO "Program" (title, host, category, description, color, "mediaFolder") VALUES ('Especial Alice In Chains', 'Auto-DJ', 'Especial', 'Meia hora só de Alice In Chains, na madrugada.', '#3f6212', 'Alice In Chains') RETURNING id) INSERT INTO ids SELECT 'esp:Alice In Chains', id FROM p;
WITH p AS (INSERT INTO "Program" (title, host, category, description, color, "mediaFolder") VALUES ('Especial Queen', 'Auto-DJ', 'Especial', 'Meia hora só de Queen, na madrugada.', '#a16207', 'Queen') RETURNING id) INSERT INTO ids SELECT 'esp:Queen', id FROM p;
WITH p AS (INSERT INTO "Program" (title, host, category, description, color, "mediaFolder") VALUES ('Especial Megadeth', 'Auto-DJ', 'Especial', 'Meia hora só de Megadeth, na madrugada.', '#334155', 'Megadeth') RETURNING id) INSERT INTO ids SELECT 'esp:Megadeth', id FROM p;
WITH p AS (INSERT INTO "Program" (title, host, category, description, color, "mediaFolder") VALUES ('Especial Red Hot Chili Peppers', 'Auto-DJ', 'Especial', 'Meia hora só de Red Hot Chili Peppers, na madrugada.', '#c2410c', 'Red Hot Chili Peppers') RETURNING id) INSERT INTO ids SELECT 'esp:Red Hot Chili Peppers', id FROM p;
WITH p AS (INSERT INTO "Program" (title, host, category, description, color, "mediaFolder") VALUES ('Especial Ramones', 'Auto-DJ', 'Especial', 'Meia hora só de Ramones, na madrugada.', '#15803d', 'Ramones') RETURNING id) INSERT INTO ids SELECT 'esp:Ramones', id FROM p;
WITH p AS (INSERT INTO "Program" (title, host, category, description, color, "mediaFolder") VALUES ('Especial Black Sabbath', 'Auto-DJ', 'Especial', 'Meia hora só de Black Sabbath, na madrugada.', '#57534e', 'Black Sabbath') RETURNING id) INSERT INTO ids SELECT 'esp:Black Sabbath', id FROM p;
WITH p AS (INSERT INTO "Program" (title, host, category, description, color, "mediaFolder") VALUES ('Especial Coldplay', 'Auto-DJ', 'Especial', 'Meia hora só de Coldplay, na madrugada.', '#0369a1', 'Coldplay') RETURNING id) INSERT INTO ids SELECT 'esp:Coldplay', id FROM p;
WITH p AS (INSERT INTO "Program" (title, host, category, description, color, "mediaFolder") VALUES ('Especial Def Leppard', 'Auto-DJ', 'Especial', 'Meia hora só de Def Leppard, na madrugada.', '#86198f', 'Def Leppard') RETURNING id) INSERT INTO ids SELECT 'esp:Def Leppard', id FROM p;
WITH p AS (INSERT INTO "Program" (title, host, category, description, color, "mediaFolder") VALUES ('Especial The Smiths', 'Auto-DJ', 'Especial', 'Meia hora só de The Smiths, na madrugada.', '#4338ca', 'The Smiths') RETURNING id) INSERT INTO ids SELECT 'esp:The Smiths', id FROM p;
WITH p AS (INSERT INTO "Program" (title, host, category, description, color, "mediaFolder") VALUES ('Especial David Bowie', 'Auto-DJ', 'Especial', 'Meia hora só de David Bowie, na madrugada.', '#b45309', 'David Bowie') RETURNING id) INSERT INTO ids SELECT 'esp:David Bowie', id FROM p;
UPDATE "MediaItem" SET "programId" = (SELECT id FROM ids WHERE k = 'esp:Black Sabbath') WHERE filename IN ('Rock Anos 70/Black Sabbath - Paranoid.mp3', 'Rock Anos 70/Black Sabbath - Changes.mp3');
UPDATE "MediaItem" SET "programId" = (SELECT id FROM ids WHERE k = 'esp:David Bowie') WHERE filename IN ('Rock Anos 70/David Bowie - Suffragette City.mp3');
UPDATE "MediaItem" SET "programId" = (SELECT id FROM ids WHERE k = 'esp:Queen') WHERE filename IN ('Rock Anos 70/Queen - Bohemian Rhapsody.mp3');
UPDATE "MediaItem" SET "programId" = (SELECT id FROM ids WHERE k = 'esp:Ramones') WHERE filename IN ('Rock Anos 70/Ramones - I Wanna Be Sedated.mp3');
SELECT count(*) AS programas FROM "Program";
SELECT count(*) AS blocos FROM "ProgramSlot";
COMMIT;
